+    let error = run(remote.execute(RestRequest {
+        method: "GET".into(),
+        url: "/native".into(),
+        headers: indexmap::IndexMap::from([
+            ("Authorization".into(), "Bearer original".into()),
+            (
+                "Tealstreet-Authorization".into(),
+                "bad original proxy".into(),
+            ),
